('5.2.01','5.2.01','5','2','01',NULL,NULL,NULL,'Belanja Modal Tanah',NULL,'2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019',NULL,NULL,0x00,NULL,NULL),
('5.2.01.01','5.2.01.01','5','2','01','01',NULL,NULL,'Belanja Modal Tanah','Digunakan untuk mencatat seluruh pengeluaran yang dilakukan untuk pengadaan/pembelian/pembebasan penyelesaian, balik nama, pengosongan, penimbunan, perataan, pematangan tanah, pembuatan sertifikat tanah serta pengeluaran-pengeluaran lain yang bersifat administratif sehubungan dengan perolehan hak dan kewajiban atas tanah pada saat pembebasan/pembayaran ganti rugi sampai tanah tersebut siap digunakan/pakai (swakelola/kontraktual). Pencatatan tersebut berupa belanja modal tanah persil, belanja modal tanah non persil, dan belanja modal lapangan.','2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019',NULL,NULL,0x00,NULL,NULL),
