(2863,'1.5.05.01.01.001','1.5.05.01.01.001','1','5','05','01','01','001','Akumulasi Amortisasi Aset Tidak Berwujud-Lisensi dan Frenchise','Digunakan untuk mencatat akumulasi amortisasi aset tidak berwujud-lisensi dan frenchise.','2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019',NULL,NULL,0x00,NULL,NULL,'2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019'),
(2864,'1.5.05.01.01.002','1.5.05.01.01.002','1','5','05','01','01','002','Akumulasi Amortisasi Aset Tidak Berwujud-Hak Cipta','Digunakan untuk mencatat akumulasi amortisasi aset tidak berwujud-hak cipta.','2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019',NULL,NULL,0x00,NULL,NULL,'2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019'),
(2865,'1.5.05.01.01.003','1.5.05.01.01.003','1','5','05','01','01','003','Akumulasi Amortisasi Aset Tidak Berwujud-Hak Paten','Digunakan untuk mencatat akumulasi amortisasi aset tidak berwujud-hak paten.','2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019',NULL,NULL,0x00,NULL,NULL,'2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019'),
(2866,'1.5.05.01.01.004','1.5.05.01.01.004','1','5','05','01','01','004','Akumulasi Amortisasi Aset Tidak Berwujud-Software','Digunakan untuk mencatat akumulasi amortisasi aset tidak berwujud-software.','2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019',NULL,NULL,0x00,NULL,NULL,'2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019'),
(2867,'1.5.05.01.01.005','1.5.05.01.01.005','1','5','05','01','01','005','Akumulasi Amortisasi Aset Tidak Berwujud-Kajian','Digunakan untuk mencatat akumulasi amortisasi aset tidak berwujud-kajian.','2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019',NULL,NULL,0x00,NULL,NULL,'2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019'),
(2868,'1.5.06','1.5.06','1','5','06',NULL,NULL,NULL,'Akumulasi Penyusutan Aset Lainnya',NULL,'2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019',NULL,NULL,0x00,NULL,NULL,'2019-10-18','Peraturan Menteri Dalam Negeri Nomor 90 Tahun 2019'),
